from prusa_kload import extract_gcode_filament_metadata, parse_gcode_filament


def test_prusaslicer_header_and_multi_extruder(tmp_path):
    gcode = tmp_path / "model.gcode"
    gcode.write_text(
        "; generated by PrusaSlicer 2.8.0\n"
        "; filament_type = PLA;PETG\n"
        "G28\n",
        encoding="utf-8",
    )
    raw, first = extract_gcode_filament_metadata(str(gcode))
    assert raw == "PLA;PETG"
    assert first == "PLA"
    assert parse_gcode_filament(str(gcode)) == "PLA"


def test_orcaslicer_bambu_quoted_and_comma(tmp_path):
    gcode = tmp_path / "orca.gcode"
    gcode.write_text(
        "; BambuStudio 1.9\n"
        '; filament_type = "PETG","PLA"\n'
        "M104 S230\n",
        encoding="utf-8",
    )
    assert parse_gcode_filament(str(gcode)) == "PETG"


def test_cura_filament_headers(tmp_path):
    gcode = tmp_path / "cura.gcode"
    gcode.write_text(
        ";FLAVOR:Marlin\n"
        ";FILAMENT_TYPE:ASA\n"
        "G28\n",
        encoding="utf-8",
    )
    assert parse_gcode_filament(str(gcode)) == "ASA"

    gcode2 = tmp_path / "cura_mat.gcode"
    gcode2.write_text(
        ";FLAVOR:Marlin\n"
        ";MATERIAL.NAME:TPU\n"
        "G28\n",
        encoding="utf-8",
    )
    assert parse_gcode_filament(str(gcode2)) == "TPU"


def test_ignores_filament_used_comments(tmp_path):
    gcode = tmp_path / "used.gcode"
    gcode.write_text(
        "; filament used [mm] = 1234.5\n"
        "; filament_diameter = 1.75\n"
        "; filament_type = ABS\n",
        encoding="utf-8",
    )
    assert parse_gcode_filament(str(gcode)) == "ABS"


def test_large_file_head_and_tail_only(tmp_path):
    padding = ("G1 X10 Y10 E0.1 ; filler line for large gcode\n" * 5000)
    assert len(padding.encode("utf-8")) > 200_000

    head_file = tmp_path / "large_head.gcode"
    head_file.write_text("; filament_type = PC\n" + padding, encoding="utf-8")
    assert parse_gcode_filament(str(head_file)) == "PC"

    tail_file = tmp_path / "large_tail.gcode"
    tail_file.write_text(padding + "; filament_type = PA\n", encoding="utf-8")
    assert parse_gcode_filament(str(tail_file)) == "PA"


def test_missing_metadata_returns_none(tmp_path):
    gcode = tmp_path / "plain.gcode"
    gcode.write_text("G28\nG1 X10 F1200\n", encoding="utf-8")
    assert parse_gcode_filament(str(gcode)) is None
    assert parse_gcode_filament(str(tmp_path / "missing.gcode")) is None

